function basis(){return axis===0?[new THREE.Vector3(0,0,1),new THREE.Vector3(0,1,0)]:axis===2?[new THREE.Vector3(1,0,0),new THREE.Vector3(0,1,0)]:[new THREE.Vector3(1,0,0),new THREE.Vector3(0,0,1)];}
