for(const b of document.querySelectorAll('[data-axis]'))b.onclick=()=>{axis=Number(b.dataset.axis);document.querySelectorAll('[data-axis]').forEach(x=>x.classList.toggle('active',x===b));update();};$('slider').oninput=e=>{pos=Number(e.target.value);update()};$('reverse').onchange=e=>{reverse=e.target.checked;update()};$('enabled').onchange=e=>{cut=e.target.checked;update()};for(const id of ['shell','furniture','plane','terrain'])$(id).onchange=update;$('iso').onclick=()=>setCamera(false);$('ortho').onclick=()=>setCamera(true);$('isoOrtho').onclick=setIsometric;$('reset').onclick=()=>{axis=0;pos=10;reverse=false;cut=true;$('slider').value=10;$('enabled').checked=true;$('reverse').checked=false;document.querySelectorAll('[data-axis]').forEach(b=>b.classList.toggle('active',b.dataset.axis==='0'));setCamera(false);update()};$('download').onclick=()=>{let a=document.createElement('a');a.download=MODEL.id+'-section-'+axis+'-'+pos+'.png';a.href=$('section').toDataURL();a.click()};$('fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();new ResizeObserver(resize).observe(viewer);
